func:
var on = (msg.payload === 1 || msg.payload === true);
flow.set("sp_enabled", on);
node.status({
    fill: on ? "green" : "grey",
    shape: "dot",
    text: on ? "ENABLED" : "DISABLED"
});
if (!on) {
    flow.set("sp_load_exceed_start", 0);
}
return null;

var val = msg.payload;
if (typeof val !== 'number' || val < 100 || val > 2000) return null;
flow.set("sp_p_rated", val);
node.status({fill: "blue", shape: "dot", text: val + "W rated"});
return null;

var v = Number(msg.payload) || 0;
flow.set("sp_pv_voltage", v);

// --- Estimation model ---
// Linear interpolation: ratio = (Voc - VOC_ZERO) / (VOC_FULL - VOC_ZERO)
// P_est = P_RATED * ratio * gain
// Adjust VOC_ZERO and VOC_FULL to match your panels.
var VOC_ZERO = 30;  // V below which power is negligible
var VOC_FULL = 80;  // V at full sun (peak Voc from your graph)

var pRated = flow.get("sp_p_rated") || 500;
var gain   = flow.get("sp_gain")    || 1.0;

var ratio = Math.max(0, Math.min(1, (v - VOC_ZERO) / (VOC_FULL - VOC_ZERO)));
var pEst  = pRated * ratio * gain;

flow.set("sp_pv_estimated", pEst);
flow.set("sp_voc_ratio", ratio);

node.status({
    fill: v > VOC_ZERO ? "yellow" : "grey",
    shape: "dot",
    text: v.toFixed(1) + "V -> ~" + pEst.toFixed(0) + "W (gain:" + gain.toFixed(2) + ")"
});
return null;

var w = Number(msg.payload) || 0;
flow.set("sp_pv_power", w);
node.status({fill: "yellow", shape: "dot", text: w.toFixed(0) + " W actual"});
return null;

var w = Number(msg.payload) || 0;
flow.set("sp_ac_load", w);

// Rolling average over last 60 samples (~60s at 1 update/sec)
var samples = flow.get("sp_ac_samples") || [];
samples.push(w);
if (samples.length > 60) samples.shift();
flow.set("sp_ac_samples", samples);

var sum = 0;
for (var i = 0; i < samples.length; i++) sum += samples[i];
var avg = sum / samples.length;
flow.set("sp_ac_load_avg", avg);

node.status({
    fill: "blue", shape: "dot",
    text: w.toFixed(0) + "W (avg:" + avg.toFixed(0) + "W, " + samples.length + "s)"
});
return null;

var pct = Number(msg.payload);
if (isNaN(pct)) return null;
flow.set("sp_soc", pct);
var fill = pct > 50 ? "green" : (pct > 30 ? "yellow" : "red");
node.status({fill: fill, shape: "dot", text: pct.toFixed(1) + "%"});
return null;

// === Solar Priority — 3-State Decision Logic ===
//
// SHORE:  Voc-estimated power vs avg load -> probe if solar looks sufficient
// PROBE:  Disconnect shore, wait for MPPT ramp, measure actual PV
//         -> SOLAR if confirmed, -> SHORE if not (+ self-tune gain)
// SOLAR:  Actual PV vs avg load -> SHORE after 15s grace if overloaded
//
// Self-tuning: after each probe, compares estimated vs actual power
// and adjusts 'gain' factor so future estimates improve.

// ---- Tunable thresholds ----
var SOLAR_MARGIN   = 1.2;      // PV must exceed load by 20%
var MIN_EST_W      = 100;      // Min estimated watts to trigger probe
var RAMP_TIME_MS   = 60000;    // 60s for MPPTs to reach output
var LOAD_EXCEED_MS = 15000;    // 15s grace before returning to shore
var COOLDOWN_MS    = 300000;   // 5 min between transitions
var MIN_SOC        = 40;       // Won't probe below this SOC %
var SOC_EMERGENCY  = 30;       // Immediate shore reconnect

// ---- Read inputs ----
var enabled    = flow.get("sp_enabled") || false;
var pvVoc      = flow.get("sp_pv_voltage");
var pvEst      = flow.get("sp_pv_estimated");
var pvPower    = flow.get("sp_pv_power");
var acLoadAvg  = flow.get("sp_ac_load_avg");
var soc        = flow.get("sp_soc");

// ---- Persisted state ----
var state           = flow.get("sp_state") || "shore";
var lastTransition  = flow.get("sp_last_transition") || 0;
var probeStart      = flow.get("sp_probe_start") || 0;
var probeEstimate   = flow.get("sp_probe_estimate") || 0;
var loadExceedStart = flow.get("sp_load_exceed_start") || 0;
var gain            = flow.get("sp_gain") || 1.0;

var now = Date.now();
var command = null;   // null=no change, 0=shore, 1=ignore-AC
var statusText = "";
var statusFill = "grey";

// Helper: return to shore
function goShore(reason) {
    command = 0;
    state = "shore";
    lastTransition = now;
    loadExceedStart = 0;
    probeStart = 0;
    statusText = "-> SHORE (" + reason + ")";
}

// Helper: update gain with a new observation
function updateGain(estimated, actual) {
    if (estimated <= 0 || actual <= 0) return;
    var sample = actual / estimated;
    gain = 0.85 * gain + 0.15 * sample;
    gain = Math.max(0.3, Math.min(3.0, gain)); // clamp
    flow.set("sp_gain", gain);
}

var hasData = pvVoc !== undefined && pvVoc !== null &&
              acLoadAvg !== undefined && acLoadAvg !== null &&
              soc !== undefined && soc !== null;

if (!enabled) {
    // ---- DISABLED ----
    if (state !== "shore") goShore("disabled");
    else statusText = "DISABLED";
    statusFill = "grey";

} else if (!hasData) {
    // ---- MISSING DATA ----
    if (state !== "shore") goShore("no data");
    else statusText = "Waiting for data";
    statusFill = "red";

} else {
    var cooldownOk   = (now - lastTransition) >= COOLDOWN_MS;
    var cooldownLeft  = Math.max(0, Math.ceil((COOLDOWN_MS - (now - lastTransition)) / 1000));
    var load = acLoadAvg;

    // ======== SHORE ========
    if (state === "shore") {
        var est = pvEst || 0;
        if (cooldownOk &&
            est >= MIN_EST_W &&
            est >= load * SOLAR_MARGIN &&
            soc >= MIN_SOC) {
            // Start probe
            command = 1;
            state = "probe";
            probeStart = now;
            probeEstimate = est;
            lastTransition = now;
            loadExceedStart = 0;
            statusFill = "yellow";
            statusText = "-> PROBE (est:" + est.toFixed(0) + "W > load:" + load.toFixed(0) + "W)";
        } else {
            statusFill = "blue";
            statusText = "SHORE | Est:" + est.toFixed(0) + "W Load:" + load.toFixed(0) + "W" +
                         " Voc:" + (pvVoc||0).toFixed(0) + "V SOC:" + soc.toFixed(0) + "%" +
                         " g:" + gain.toFixed(2);
            if (!cooldownOk) statusText += " [CD:" + cooldownLeft + "s]";
        }

    // ======== PROBE ========
    } else if (state === "probe") {
        var elapsed = now - probeStart;

        if (soc < SOC_EMERGENCY) {
            goShore("emergency SOC:" + soc.toFixed(0) + "%");
            statusFill = "red";

        } else if (elapsed < RAMP_TIME_MS) {
            // Still ramping — just wait
            var rampLeft = Math.ceil((RAMP_TIME_MS - elapsed) / 1000);
            var pv = pvPower || 0;
            statusFill = "yellow";
            statusText = "PROBE | Ramping " + rampLeft + "s  PV:" + pv.toFixed(0) + "W" +
                         " Load:" + load.toFixed(0) + "W";

        } else {
            // Ramp done — evaluate actual production
            var actual = pvPower || 0;

            // Self-tune regardless of outcome
            updateGain(probeEstimate, actual);

            if (actual >= load * SOLAR_MARGIN) {
                // Probe succeeded
                state = "solar";
                loadExceedStart = 0;
                statusFill = "green";
                statusText = "-> SOLAR (PV:" + actual.toFixed(0) + "W > load:" + load.toFixed(0) + "W" +
                             " g:" + gain.toFixed(2) + ")";
            } else {
                // Probe failed
                goShore("probe: PV " + actual.toFixed(0) + "W < " +
                        (load * SOLAR_MARGIN).toFixed(0) + "W needed, g:" + gain.toFixed(2));
                statusFill = "blue";
            }
        }

    // ======== SOLAR ========
    } else {
        var actual = pvPower || 0;
        var overloaded = load > actual || soc < MIN_SOC;

        if (soc < SOC_EMERGENCY) {
            goShore("emergency SOC:" + soc.toFixed(0) + "%");
            statusFill = "red";

        } else if (overloaded) {
            if (loadExceedStart === 0) loadExceedStart = now;
            var elapsed = now - loadExceedStart;
            if (elapsed >= LOAD_EXCEED_MS) {
                goShore("load exceeded " + (LOAD_EXCEED_MS / 1000) + "s");
                statusFill = "blue";
            } else {
                var remaining = Math.ceil((LOAD_EXCEED_MS - elapsed) / 1000);
                statusFill = "yellow";
                statusText = "SOLAR ! PV:" + actual.toFixed(0) + "W < Load:" + load.toFixed(0) + "W" +
                             " [shore in " + remaining + "s]";
            }
        } else {
            loadExceedStart = 0;
            statusFill = "green";
            statusText = "SOLAR | PV:" + actual.toFixed(0) + "W Load:" + load.toFixed(0) + "W" +
                         " SOC:" + soc.toFixed(0) + "% g:" + gain.toFixed(2);
        }
    }
}

// ---- Persist ----
flow.set("sp_state", state);
flow.set("sp_last_transition", lastTransition);
flow.set("sp_probe_start", probeStart);
flow.set("sp_probe_estimate", probeEstimate);
flow.set("sp_load_exceed_start", loadExceedStart);

node.status({ fill: statusFill, shape: "dot", text: statusText });

if (command !== null) {
    return { payload: command };
}
return null;

initialize:
// Safe defaults on deploy/restart
flow.set("sp_state", "shore");
flow.set("sp_last_transition", 0);
flow.set("sp_probe_start", 0);
flow.set("sp_probe_estimate", 0);
flow.set("sp_load_exceed_start", 0);
// Preserve gain across restarts if already set
if (!flow.get("sp_gain")) flow.set("sp_gain", 1.0);
